<?php require_once 'includes/auth.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$pid=(int)$_POST['product_id'];$s=$pdo->prepare("SELECT id FROM wishlist WHERE user_id=? AND product_id=?");$s->execute([$_SESSION['user_id'],$pid]);if($s->fetch())$pdo->prepare("DELETE FROM wishlist WHERE user_id=? AND product_id=?")->execute([$_SESSION['user_id'],$pid]);else$pdo->prepare("INSERT IGNORE INTO wishlist(user_id,product_id) VALUES(?,?)")->execute([$_SESSION['user_id'],$pid]);header('Location: wishlist.php');exit;}$s=$pdo->prepare("SELECT p.*,c.name category_name FROM wishlist w JOIN products p ON p.id=w.product_id LEFT JOIN categories c ON c.id=p.category_id WHERE w.user_id=? ORDER BY w.created_at DESC");$s->execute([$_SESSION['user_id']]);$products=$s->fetchAll();$page_title='Wishlist';require 'includes/header.php';?><div class="container page-title"><span class="eyebrow">Saved pieces</span><h1>Wishlist</h1></div><section class="section container" style="padding-top:10px"><div class="grid"><?php foreach($products as $p):?><article class="product-card"><a href="product.php?id=<?=$p['id']?>"><div class="product-image"><?php if($p['main_image']): ?><img class="product-main-image" src="<?=e($p['main_image'])?>" alt="<?=e($p['name'])?>"><?php if(!empty($p['secondary_image'])): ?><img class="product-secondary-image" src="<?=e($p['secondary_image'])?>" alt="<?=e($p['name'])?> alternate view"><?php endif; ?><?php else: ?><span class="placeholder">L</span><?php endif; ?></div><div class="product-info"><small><?=e($p['category_name']??'Collection')?></small><h3><?=e($p['name'])?></h3><span class="price"><?=money(sale_price($p))?></span></div></a><form method="post" style="padding:0 16px 16px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="btn light small">Remove</button></form></article><?php endforeach;?></div><?php if(!$products):?><div class="empty">No saved products yet.</div><?php endif;?></section><?php require 'includes/footer.php';?>
